<template>
  <section aria-label="NEWS2评估来源登记与选择" class="news2-input">
    <p v-if="!allowed">请先选择有权限的患者、原住院和原观测窗。</p>
    <template v-else>
      <p>患者 #{{ patientId }} · 原住院 {{ admissionId }} · 窗口 {{ windowId }}。只选一个完整原点测量，不合并不同时间的最新值；来源登记不自动计算、选中或启用AI。</p>
      <el-form-item label="明确选择NEWS2评估来源"><el-select v-model="selectedId" aria-label="待计算NEWS2评估来源" clearable :disabled="loading || checking || creating || revoking" placeholder="明确选择，登记成功不会自动选中"><el-option v-for="row in sources" :key="row.assessment_id" :value="row.assessment_id" :disabled="row.status !== 'active' || row.eligible !== true" :label="`${row.observed_at} · ${row.assessment_id} · ${row.status === 'active' ? '活动来源' : '已撤销'}`" /></el-select></el-form-item>
      <el-button :loading="loading" :disabled="creating || revoking" @click="loadSources">刷新NEWS2评估目录</el-button>
      <p>目录共 {{ total ?? "未知" }} 项；本页仅显示所选窗口的来源，可翻页继续核对。目录不证明临床适用或模型已验证；未知适用性可保留，不自动视为合规。</p><el-pagination v-if="total > 50" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next" @current-change="loadSources" />
      <p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
      <template v-if="selected"><p>已核对 {{ selected.assessment_id }} · {{ selected.content_hash }}；原点 {{ selected.point_id }}，规则版本 {{ selected.rule_profile_id }}。生成时仍复核原来源。</p><el-button @click="detailOpen = true">核对所选NEWS2原来源</el-button><template v-if="selected.can_revoke === true"><el-input v-model="revokeReason" aria-label="NEWS2评估撤销依据" maxlength="1000" placeholder="明确填写撤销原因" /><el-button type="danger" :disabled="!revokeReason.trim()" :loading="revoking" @click="revoke">撤销所选NEWS2评估</el-button></template></template>
      <el-collapse><el-collapse-item title="登记单个原点测量的NEWS2评估来源">
        <el-button :loading="candidateLoading" :disabled="creating" @click="loadCandidates">读取本窗口原点测与审核规则</el-button>
        <p>年龄按原观察时刻核实，妊娠及SpO₂规则明确选择，均不预填。人工依据只作来源声明，不是独立临床验证。</p>
        <el-form label-position="top" :disabled="creating" @submit.prevent>
          <el-form-item label="本窗口单个原点测量"><el-select v-model="pointId" aria-label="NEWS2原点测量" clearable placeholder="明确选择一个原点，不自动选择最近值"><el-option v-for="row in candidates" :key="row.observation_id" :value="row.observation_id" :label="`${row.observed_at} · ${row.observation_id}`" /></el-select></el-form-item>
          <template v-if="point"><p>原观察 {{ point.observed_at }}；系统登记 {{ point.recorded_at }}。原内容摘要 {{ point.content_hash }}</p><el-table :data="rawValues" aria-label="NEWS2所选点测原值"><el-table-column prop="label" label="指标" /><el-table-column prop="display" label="原值或缺失原因" /><el-table-column prop="unit" label="原单位" /></el-table><p>原氧疗 {{ point.payload.supplemental_oxygen }}；原意识 {{ point.payload.consciousness ? `${point.payload.consciousness.system} · ${point.payload.consciousness.code}` : '未记录' }}。不能用护理整数或GCS补齐。</p><p v-if="conflicts.length">此时点存在 {{ conflicts.length }} 组重复/冲突，将按规则保留；不会任取最后一条消除冲突。</p></template>
          <el-form-item label="已审核固定规则版本"><el-select v-model="profileId" aria-label="NEWS2审核规则版本" clearable placeholder="明确选择已发布版本"><el-option v-for="row in profiles" :key="row.rule_profile_id" :value="row.rule_profile_id" :label="`${row.name} · ${row.rule_id} · v${row.revision}`" /></el-select></el-form-item>
          <el-form-item label="原观察时年龄（整岁）"><el-input v-model="form.age" aria-label="NEWS2原观察时年龄" inputmode="numeric" placeholder="明确填写0至130，不按今天年龄或空值补0" /></el-form-item>
          <el-input v-model="form.age_basis_note" aria-label="NEWS2原年龄核实依据" type="textarea" maxlength="1000" placeholder="至少20字，记录原观察时年龄的核实依据" />
          <el-form-item label="原观察时妊娠状态"><el-select v-model="form.pregnancy_status" aria-label="NEWS2妊娠状态" placeholder="明确选择，不预填非妊娠"><el-option label="妊娠" value="pregnant" /><el-option label="已核实未妊娠" value="not_pregnant" /><el-option label="明确不适用妊娠条件" value="not_applicable" /><el-option label="未知，保留适用性缺口" value="unknown" /></el-select></el-form-item>
          <el-input v-model="form.pregnancy_basis_note" aria-label="NEWS2妊娠状态核实依据" type="textarea" maxlength="1000" placeholder="至少20字，明确原时点的事实或尚未核实的缺口" />
          <el-form-item label="临床选定SpO₂评分规则"><el-select v-model="form.spo2_scale" aria-label="NEWS2血氧评分规则" placeholder="明确选择，不从装置或SpO₂值推断"><el-option label="Scale 1" :value="1" /><el-option v-if="canDeclareScale2" label="Scale 2（须临床授权及独立依据）" :value="2" /></el-select></el-form-item>
          <p v-if="!canDeclareScale2">当前服务回执未授权声明Scale 2；这不影响选择已有、由有资格临床人员登记的Scale 2评估。</p>
          <template v-if="form.spo2_scale === 2"><p>仅适用于已有血气确认及临床决定的88–92目标范围；本表不替代临床决定，不自动调整氧疗。</p><el-checkbox v-model="form.hypercapnic_confirmed">已核对血气确认的高碳酸性呼吸衰竭依据</el-checkbox><el-input v-model="form.blood_gas_reference" aria-label="NEWS2血气确认依据" type="textarea" maxlength="1000" placeholder="至少20字，填写实际血气确认记录依据" /><el-checkbox v-model="form.decision_confirmed">已核对临床决定使用Scale 2及88–92目标的记录</el-checkbox><el-input v-model="form.clinical_decision_reference" aria-label="NEWS2临床Scale2决定依据" type="textarea" maxlength="1000" placeholder="至少20字，填写实际临床决定记录依据" /></template>
          <el-button type="primary" :disabled="!canCreate" :loading="creating" @click="create">仅登记NEWS2评估来源</el-button>
        </el-form>
      </el-collapse-item></el-collapse>
    </template>
    <el-dialog v-model="detailOpen" title="NEWS2原评估来源复核" width="min(1000px,96vw)"><template v-if="allowed && selected"><p>评估 {{ selected.assessment_id }} · 原窗口 {{ selected.window_id }} · 原点 {{ selected.point_id }} · 规则 {{ selected.rule_profile_id }}</p><p>原观察 {{ selected.observed_at }}；本次登记 {{ selected.created_at }}。来源治理通过不代表适用性或临床验证。</p><p>声明原年龄 {{ selected.specialist_source?.age_at_observation_years }}；妊娠 {{ selected.specialist_source?.pregnancy_status }}；Scale {{ selected.specialist_source?.spo2_scale }}。</p><p>年龄核实依据：{{ selected.snapshot?.attestation?.age_basis_note }}</p><p>妊娠状态核实依据：{{ selected.snapshot?.attestation?.pregnancy_basis_note }}</p><p>原临床资格记录：{{ selected.snapshot?.author_qualification?.role_at_creation }}；此处核对事实来源，不赋予当前临床授权。</p><el-table :data="selectedRawValues" aria-label="NEWS2所选评估冻结原测量"><el-table-column prop="label" label="原指标" /><el-table-column prop="display" label="原值或缺失原因" /><el-table-column prop="unit" label="原单位" /></el-table><p>原氧疗 {{ selected.snapshot?.point?.payload?.supplemental_oxygen }}；原意识 {{ JSON.stringify(selected.snapshot?.point?.payload?.consciousness) }}。原值只读，不自动补齐。</p></template></el-dialog>
  </section>
</template>
<script setup>
import { computed, onActivated, onBeforeUnmount, onDeactivated, ref, watch } from "vue";
import { useStore } from "vuex";
import { createNews2Assessment, getNews2Assessment, getNews2Assessments, getNews2Candidates, news2AssessmentMatches, revokeNews2Assessment } from "@/api/aiNews2";
const props = defineProps({ patientId: { type: Number, required: true }, admissionId: { type: String, required: true }, windowId: { type: String, required: true }, active: { type: Boolean, default: true } });
const emit = defineEmits(["selection", "availability"]), store = useStore();
const roles = computed(() => store.getters["user/permissions"] || []), allowed = computed(() => props.active && !!store.state.user.accessToken && Number.isSafeInteger(props.patientId) && props.patientId > 0 && !!props.admissionId && !!props.windowId && roles.value.some(role => ["nurse", "doctor", "director", "admin", "super_admin"].includes(role)));
const blank = () => ({ age: "", age_basis_note: "", pregnancy_status: "", pregnancy_basis_note: "", spo2_scale: "", hypercapnic_confirmed: false, decision_confirmed: false, blood_gas_reference: "", clinical_decision_reference: "" });
const form = ref(blank()), candidates = ref([]), profiles = ref([]), conflictGroups = ref([]), pointId = ref(""), profileId = ref(""), canCreateScale2 = ref(false), candidatesWindowHash = ref(""), sources = ref([]), page = ref(1), total = ref(null), selectedId = ref(""), selected = ref(null), loading = ref(false), checking = ref(false), candidateLoading = ref(false), creating = ref(false), revoking = ref(false), error = ref(""), notice = ref(""), revokeReason = ref(""), detailOpen = ref(false);
let epoch = 0, listSequence = 0, candidateSequence = 0, detailSequence = 0, inactive = false;
const scopeKey = () => JSON.stringify([props.patientId, props.admissionId, props.windowId, props.active, store.state.user.accessToken, roles.value]);
const capture = () => ({ epoch, key: scopeKey(), patientId: props.patientId, admissionId: props.admissionId, windowId: props.windowId });
const current = ticket => ticket.epoch === epoch && ticket.key === scopeKey() && allowed.value && !inactive;
const query = ticket => ({ patient_id: ticket.patientId, admission_id: ticket.admissionId, window_id: ticket.windowId });
const clearSelection = () => { detailSequence++; selectedId.value = ""; selected.value = null; checking.value = false; revokeReason.value = ""; detailOpen.value = false; emit("selection", null); emit("availability", false); };
function clearDraft() { pointId.value = ""; profileId.value = ""; form.value = blank(); }
function reset() { epoch++; listSequence++; candidateSequence++; clearSelection(); clearDraft(); candidates.value = []; profiles.value = []; conflictGroups.value = []; sources.value = []; page.value = 1; total.value = null; candidatesWindowHash.value = ""; canCreateScale2.value = false; loading.value = candidateLoading.value = creating.value = revoking.value = false; error.value = notice.value = ""; }
const canDeclareScale2 = computed(() => canCreateScale2.value && roles.value.some(role => ["doctor", "director", "super_admin"].includes(role)));
const point = computed(() => candidates.value.find(row => row.observation_id === pointId.value)), profile = computed(() => profiles.value.find(row => row.rule_profile_id === profileId.value));
const labels = { respiratory_rate: "呼吸率", spo2: "SpO₂", systolic_bp: "收缩压", pulse_rate: "脉搏", temperature: "体温", heart_rate: "心率（不替代脉搏）" };
const rawValues = computed(() => Object.entries(point.value?.payload?.measurements || {}).map(([key, value]) => ({ label: labels[key] || key, display: value.value ?? `未测（${value.absent_reason}）`, unit: value.unit })));
const selectedRawValues = computed(() => Object.entries(selected.value?.snapshot?.point?.payload?.measurements || {}).map(([key, value]) => ({ label: labels[key] || key, display: value.value ?? `未测（${value.absent_reason}）`, unit: value.unit })));
const conflicts = computed(() => conflictGroups.value.filter(row => row.observed_at === point.value?.observed_at));
const canCreate = computed(() => allowed.value && !creating.value && !!point.value && !!profile.value && /^(?:0|[1-9]\d{0,2})$/.test(form.value.age) && Number(form.value.age) <= 130 && form.value.age_basis_note.trim().length >= 20 && !!form.value.pregnancy_status && form.value.pregnancy_basis_note.trim().length >= 20 && (form.value.spo2_scale === 1 || (form.value.spo2_scale === 2 && canDeclareScale2.value && form.value.hypercapnic_confirmed && form.value.decision_confirmed && form.value.blood_gas_reference.trim().length >= 20 && form.value.clinical_decision_reference.trim().length >= 20)));
async function loadSources() { clearSelection(); if (!allowed.value || inactive) return; const ticket = capture(), seq = ++listSequence; loading.value = true; sources.value = []; error.value = ""; try { const res = await getNews2Assessments({ ...query(ticket), page: page.value, page_size: 50 }); if (!current(ticket) || seq !== listSequence) return; if (!Array.isArray(res.data?.items) || res.data.items.some(row => !news2AssessmentMatches(row, ticket.patientId, ticket.admissionId))) throw new Error("评估目录与原患者或住院不一致"); sources.value = res.data.items.filter(row => row.window_id === ticket.windowId); total.value = res.data.total; } catch (failure) { if (current(ticket) && seq === listSequence) error.value = failure?.message || "NEWS2评估目录未能读取"; } finally { if (current(ticket) && seq === listSequence) loading.value = false; } }
async function loadCandidates() { if (!allowed.value || inactive || creating.value) return; clearDraft(); candidates.value = []; profiles.value = []; const ticket = capture(), seq = ++candidateSequence; candidateLoading.value = true; error.value = ""; try { const res = await getNews2Candidates(query(ticket)); if (!current(ticket) || seq !== candidateSequence) return; const data = res.data, window = data?.window; if (window?.patient_id !== ticket.patientId || window.admission_id !== ticket.admissionId || window.window_id !== ticket.windowId || !/^[a-f0-9]{64}$/.test(window.content_hash || "") || !Array.isArray(data.points) || data.points.some(row => row.patient_id !== ticket.patientId || row.admission_id !== ticket.admissionId || row.status !== "active" || !/^[a-f0-9]{64}$/.test(row.content_hash || "")) || !Array.isArray(data.rule_profiles)) throw new Error("原点、规则或窗口回执与所选范围不一致"); candidates.value = data.points; profiles.value = data.rule_profiles.filter(row => row.status === "published" && row.revision === 2 && row.rule_id === "news2_2017" && /^[a-f0-9]{64}$/.test(row.content_hash || "")); conflictGroups.value = data.conflict_groups || []; candidatesWindowHash.value = window.content_hash; canCreateScale2.value = data.can_create_scale2 === true; } catch (failure) { if (current(ticket) && seq === candidateSequence) error.value = failure?.message || "原点和规则未能核对"; } finally { if (current(ticket) && seq === candidateSequence) candidateLoading.value = false; } }
async function create() { if (!canCreate.value || inactive) return; clearSelection(); const ticket = capture(), originalPoint = point.value, originalProfile = profile.value; const body = { ...query(ticket), expected_window_hash: candidatesWindowHash.value, point_id: originalPoint.observation_id, expected_point_hash: originalPoint.content_hash, rule_profile_id: originalProfile.rule_profile_id, expected_rule_profile_hash: originalProfile.content_hash, age_at_observation_years: Number(form.value.age), age_basis_note: form.value.age_basis_note.trim(), pregnancy_status: form.value.pregnancy_status, pregnancy_basis_note: form.value.pregnancy_basis_note.trim(), spo2_scale: form.value.spo2_scale, scale2_review: form.value.spo2_scale === 1 ? null : { hypercapnic_respiratory_failure_confirmed: true, clinical_decision_confirmed: true, target_range: "88-92", blood_gas_reference: form.value.blood_gas_reference.trim(), clinical_decision_reference: form.value.clinical_decision_reference.trim() } }; creating.value = true; try { const res = await createNews2Assessment(body); if (!current(ticket)) return; const data = res.data; if (!news2AssessmentMatches(data, ticket.patientId, ticket.admissionId, ticket.windowId) || data.window_content_hash !== body.expected_window_hash || data.point_id !== body.point_id || data.point_content_hash !== body.expected_point_hash || data.rule_profile_id !== body.rule_profile_id || data.rule_profile_content_hash !== body.expected_rule_profile_hash || data.status !== "active" || data.revision !== 1) throw new Error("登记回执与原窗口、原点或审核规则不一致"); clearDraft(); page.value = 1; await loadSources(); if (current(ticket)) notice.value = "评估来源已登记；请明确选择并复核，尚未调用模型或自动计算。"; } catch (failure) { if (current(ticket)) error.value = failure?.response?.data?.detail || failure?.message || "评估来源登记失败"; } finally { if (current(ticket)) creating.value = false; } }
async function revoke() { if (!allowed.value || inactive || selected.value?.can_revoke !== true || !revokeReason.value.trim() || revoking.value) return; const ticket = capture(), original = selected.value, withdrawalReason = revokeReason.value.trim(); clearSelection(); revoking.value = true; try { const res = await revokeNews2Assessment(original.assessment_id, { patient_id: ticket.patientId, admission_id: ticket.admissionId, expected_revision: original.revision, reason: withdrawalReason }); if (!current(ticket)) return; if (!news2AssessmentMatches(res.data, ticket.patientId, ticket.admissionId, ticket.windowId) || res.data.assessment_id !== original.assessment_id || res.data.content_hash !== original.content_hash || res.data.status !== "revoked" || res.data.revision !== original.revision + 1) throw new Error("撤销回执与原评估版本不一致"); await loadSources(); if (current(ticket)) notice.value = "原评估来源已撤销，请重新核实并明确选择，旧选择不能继续使用。"; } catch (failure) { if (current(ticket)) error.value = failure?.message || "撤销失败，请刷新核对原版本"; } finally { if (current(ticket)) revoking.value = false; } }
watch(selectedId, async id => { const ticket = capture(), seq = ++detailSequence; selected.value = null; emit("selection", null); emit("availability", false); error.value = ""; if (!id || !allowed.value || inactive) return; checking.value = true; try { const res = await getNews2Assessment(id, { patient_id: ticket.patientId, admission_id: ticket.admissionId }); if (!current(ticket) || seq !== detailSequence || selectedId.value !== id) return; const row = res.data; if (!news2AssessmentMatches(row, ticket.patientId, ticket.admissionId, ticket.windowId, true) || row.assessment_id !== id || row.status !== "active" || row.revision !== 1 || row.eligible !== true || row.freshness?.state !== "current") throw new Error("原评估、窗口、点测或规则已变化，不能作为当前计算来源"); selected.value = row; emit("selection", { news2_assessment_id: row.assessment_id, content_hash: row.content_hash }); emit("availability", true); } catch (failure) { if (current(ticket) && seq === detailSequence) error.value = failure?.message || "所选评估未能核对"; } finally { if (current(ticket) && seq === detailSequence) checking.value = false; } });
watch([pointId, profileId], () => { form.value = blank(); }, { flush: "sync" });
watch(scopeKey, () => { reset(); loadSources(); }, { immediate: true, flush: "sync" });
onDeactivated(() => { inactive = true; reset(); }); onActivated(() => { if (inactive) { inactive = false; reset(); loadSources(); } }); onBeforeUnmount(() => { inactive = true; reset(); });
</script>
<style scoped>p { line-height: 1.7; overflow-wrap: anywhere; }.el-select { width: 100%; }.el-checkbox { display: flex; white-space: normal; margin: 12px 0; }.el-button { margin-top: 10px; }</style>
